  private var isLoading: Bool = false

  // MARK: Lifecycle
  override func viewDidLoad() {
    super.viewDidLoad()

    table = cardsTable(columns: ["id", "title"])

    createButton.addTarget(self, action: #selector(createCard(_:_)))
        .forcesHidden = true

    boardPicker?.addTarget(self, action: #selector(assignBoardID(_:_)))
  }

  // MARK: Card creation
  func createCard(_:) {
    let card = Card(title: "", boardId: boardId)

    if let saveResult = cardsCollection.insert(card),
       saveResult == .success {
      card.id = saveResult.identifier
      isLoading = true

      addBoardAssignmentRow(for: card)

      createButton.isHidden = true
        .forcesHidden = true

      boardPicker?.isEnabled = false
    }
  }

  // MARK: Board assignment for new cards
  func assignBoardID(_:) {
    if isLoading {
      let row = addBoardAssignmentRow(for: card)
      isLoading = false

      createButton.isHidden = true
        .forcesHidden = true

      boardPicker?.isEnabled = true
    }
  }

  // MARK: Board assignment rows for new cards
  func addBoardAssignmentRow(_: Card) -> Int {
    let rowData = ["board_id": card.boardId, "card_title": card.title]

    return table.insert(rowData, columns: ["id", "title"])
